command:
$ErrorActionPreference = "Stop"
git fetch origin main work/search-v3-criteria --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "433e26a5278af97be4c58edc362549d52abf778a") { throw "main moved" }
if ((git rev-parse origin/work/search-v3-criteria).Trim() -ne "67ee9e1472fd4589b151ede54fd3785068c2889f") { throw "candidate moved" }

git checkout work/search-v3-criteria
if ($LASTEXITCODE -ne 0) { throw "checkout failed" }
git merge --ff-only origin/work/search-v3-criteria
if ($LASTEXITCODE -ne 0) { throw "candidate fast-forward failed" }

$delta=@(git diff --name-only 13e4f1fd2b647ba4d9f24d2b7c19fa296cf2047b..HEAD)
if ($delta.Count -ne 1 -or $delta[0] -ne "app/winui/MainWindow.xaml") {
  throw "post-validation revision changed more than XAML"
}

python -X utf8 -m unittest tests.winui.test_search_v3_contract
if ($LASTEXITCODE -ne 0) { throw "Search v3 source contract failed" }

cmd /c build.bat Release
if ($LASTEXITCODE -ne 0) { throw "Release build failed" }

if (-not (Test-Path "logs\capture-search-v3-fixed.py")) {
  throw "fixed visual capture helper missing"
}
python -X utf8 "logs\capture-search-v3-fixed.py"
if ($LASTEXITCODE -ne 0) { throw "fixed visual capture failed" }

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }

@"
feature=search-v3-criteria
main=433e26a5278af97be4c58edc362549d52abf778a
candidate=67ee9e1472fd4589b151ede54fd3785068c2889f
functional_run=37170399569
visual_revision_run_pending=this-run
"@ | Set-Content -Encoding UTF8 "logs\remote-evidence\manifest.txt"

Write-Host "SEARCH_V3_XAML_FINAL_PASS"
